package com.primehr.performancemanagement.api;import com.primehr.performancemanagement.api.PerformanceCalibrationDtos.*;import com.primehr.performancemanagement.application.PerformanceCalibrationService;import com.primehr.security.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/primehr/v1/performance-management")public class PerformanceCalibrationController{private final PerformanceCalibrationService service;private final PerformanceCalibrationPermissionGuard permission;private final AgencyScopeResolver agency;public PerformanceCalibrationController(PerformanceCalibrationService s,PerformanceCalibrationPermissionGuard p,AgencyScopeResolver a){service=s;permission=p;agency=a;}private static String actor(Authentication a){if(a==null||a.getName()==null||a.getName().isBlank())throw new org.springframework.security.access.AccessDeniedException("Authenticated employee identity is required");return a.getName();}
 @PostMapping("/rating-cases/{id}/calibration")@ResponseStatus(HttpStatus.CREATED)public CalibrationResponse open(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody OpenInput r){permission.require(PrimeHrAction.ADD,t);if(r.overrideWindow())permission.require(PrimeHrAction.APPROVE,t);return service.open(agency.resolveAgencyId(a),id,r,actor(a),c);}
 @GetMapping("/calibrations/{id}")public CalibrationResponse get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){permission.require(PrimeHrAction.ACCESS,t);return service.get(agency.resolveAgencyId(a),id,actor(a));}
 @PostMapping("/calibrations/{id}/proposal")public CalibrationResponse propose(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody ProposalInput r){permission.require(PrimeHrAction.SUBMIT,t);if(r.overrideWindow())permission.require(PrimeHrAction.APPROVE,t);return service.propose(agency.resolveAgencyId(a),id,r,actor(a),c);}
 @PostMapping("/calibrations/{id}/decisions")public CalibrationResponse decide(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody DecisionInput r){permission.require(PrimeHrAction.APPROVE,t);return service.decide(agency.resolveAgencyId(a),id,r,actor(a),c);}
 @PostMapping("/rating-cases/{id}/finalize")public FinalRatingResponse finalizeRating(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody FinalizeInput r){permission.require(PrimeHrAction.FINALIZE,t);return service.finalizeRating(agency.resolveAgencyId(a),id,r,actor(a),c);}}
